  "Reciprocity": {"Explanation": "The email offers something (assistance and a potential business opportunity) and asks for a favor (click, confirmation, or assistance) in return."},
  "Scarcity": {"Explanation": "The email creates urgency by implying limited time (\"reply this mail, by contacting me strictly on this mail address as this mail using was the one myself and my husband were using when he was still alive\") and implies a limited opportunity (\"I know you maybe wondering how i got your address but permit me to tell you that i got your contact from your country's business directory\")"},
  "Authority": {"Explanation": "The email claims credibility through a recognized institution (\"country's business directory\") and a recognized title (\"Eng. Mrs. Victoria Lulu\")"},
  "Commitment/Consistency": {"Explanation": "The email references prior behavior of choices to push further action (\"back in my country, trustee fee is within the range of 5 to 7% of the total fund\")"},
  "Liking": {"Explanation": "The email uses familiarity (\"Good day to you\") and flattery (\"I know you maybe wondering how i got your address but permit me to tell you that i got your contact from your country's business directory\") to build trust or rapport"},
  "Social proof": {"Explanation": "Not present"}
}

